import { MeshBasicNodeMaterial } from 'three/webgpu';
import { time, sin, mix, uv, color, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group, Mesh, PlaneGeometry, IcosahedronGeometry, InstancedMesh,
    Object3D, Color, PointLight, AdditiveBlending,
  } = ctx.THREE;

  const group = new Group();
  group.name = 'particle-constellation-hero';

  const colors = config.intent?.visualSpec?.colors ?? {};
  const BG = colors.background ?? '#0b0b10';
  const INK = colors.ink ?? '#16161d';
  const PAPER = colors.paper ?? '#e8ecf2';
  const ACCENT = colors.accent ?? '#ff2a38';

  const disposables = [];
  const primitiveHandles = [];

  // ---------------------------------------------------------------
  // STAGE — gradient backdrop (behind the deepest particles)
  // ---------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(9.5, 7.5);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(color(BG), color(INK), uv().y);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -4.6);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // Node-local accent rim glow near the core (subject side)
  const rimLight = new PointLight(new Color(ACCENT), 1.0, 5.0, 2.0);
  rimLight.position.set(0.6, 0.4, -1.0);
  group.add(rimLight);

  // ---------------------------------------------------------------
  // FIELD PARTICLES — 1110 paper points, depth falloff baked to color
  // ---------------------------------------------------------------
  const FIELD_COUNT = 1110;
  const CORE_COUNT = 90;

  const particleGeo = new IcosahedronGeometry(0.012, 1);
  disposables.push(particleGeo);

  const fieldMat = new MeshBasicNodeMaterial();
  fieldMat.color = new Color('#ffffff');
  const field = new InstancedMesh(particleGeo, fieldMat, FIELD_COUNT);
  field.frustumCulled = false;
  group.add(field);
  disposables.push(fieldMat);

  const paperC = new Color(PAPER);
  const bgC = new Color(BG);
  const tmpC = new Color();

  // Ellipsoidal shell 6 x 4 x 5 centered at (0, 0, -1.5)
  const fieldAnchors = new Float32Array(FIELD_COUNT * 3);
  const fieldPhase = new Float32Array(FIELD_COUNT);
  const fieldDelay = new Float32Array(FIELD_COUNT);

  for (let i = 0; i < FIELD_COUNT; i++) {
    // uniform direction on sphere
    const u = Math.random() * 2 - 1;
    const th = Math.random() * Math.PI * 2;
    const s = Math.sqrt(1 - u * u);
    const dx = s * Math.cos(th);
    const dy = s * Math.sin(th);
    const dz = u;
    const r = 0.45 + 0.55 * Math.cbrt(Math.random()); // shell bias outward
    const px = dx * 3.0 * r;
    const py = dy * 2.0 * r;
    const pz = dz * 2.5 * r - 1.5;
    fieldAnchors[i * 3] = px;
    fieldAnchors[i * 3 + 1] = py;
    fieldAnchors[i * 3 + 2] = pz;
    fieldPhase[i] = Math.random() * Math.PI * 2;

    const dist = Math.sqrt(px * px + py * py + pz * pz);
    fieldDelay[i] = (dist / 5.5) * 0.5; // stagger by distance-from-core

    // depth falloff: opacity 0.9 at z=0 -> 0.15 at z=-5, plus fog sink
    const fall = Math.max(0.15, Math.min(0.9, 0.9 + (pz / 5) * 0.75));
    const fog = Math.max(0, Math.min(1, (-pz - 4) / 6)); // near 4 far 10 approx
    tmpC.copy(paperC).multiplyScalar(fall * 0.9).lerp(bgC, fog);
    field.setColorAt(i, tmpC);
  }
  if (field.instanceColor) field.instanceColor.needsUpdate = true;

  // ---------------------------------------------------------------
  // ACCENT CORE — 90 additive emissive instances, pulse 1.5 -> 1.8 @ 0.1 Hz
  // ---------------------------------------------------------------
  const coreMat = new MeshBasicNodeMaterial();
  coreMat.colorNode = color(ACCENT).mul(
    sin(time.mul(float(Math.PI * 2 * 0.1))).mul(0.15).add(1.65)
  );
  coreMat.blending = AdditiveBlending;
  coreMat.depthWrite = false;
  coreMat.transparent = true;
  const core = new InstancedMesh(particleGeo, coreMat, CORE_COUNT);
  core.frustumCulled = false;
  group.add(core);
  disposables.push(coreMat);

  const coreAnchors = new Float32Array(CORE_COUNT * 3);
  const corePhase = new Float32Array(CORE_COUNT);
  for (let i = 0; i < CORE_COUNT; i++) {
    const u = Math.random() * 2 - 1;
    const th = Math.random() * Math.PI * 2;
    const s = Math.sqrt(1 - u * u);
    const r = 0.5 * Math.cbrt(Math.random());
    coreAnchors[i * 3] = s * Math.cos(th) * r;
    coreAnchors[i * 3 + 1] = s * Math.sin(th) * r;
    coreAnchors[i * 3 + 2] = u * r;
    corePhase[i] = Math.random() * Math.PI * 2;
  }

  // ---------------------------------------------------------------
  // TYPE — hero / subhead / caption from spec copy, verbatim
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const role = item.role ?? 'body';
    if (role === 'hero') {
      const hero = ctx.fontAtlas.createText(item.text, {
        fontSize: item.typography?.fontSize ?? 124,
        color: PAPER,
        align: 'center',
        letterSpacingPx: -1.2,
      });
      hero.position.set(0, 0.5, 0.5);
      group.add(hero);
    } else if (role === 'subhead') {
      const sub = ctx.fontAtlas.createText(item.text, {
        fontSize: item.typography?.fontSize ?? 40,
        color: PAPER,
        align: 'center',
        letterSpacingPx: 0.8,
      });
      sub.position.set(0, -0.25, 0.5);
      group.add(sub);
    } else if (role === 'caption') {
      const cap = ctx.fontAtlas.createText(item.text, {
        fontSize: item.typography?.fontSize ?? 18,
        color: ACCENT,
        align: 'center',
        letterSpacingPx: 1.5,
      });
      cap.position.set(0, -2.25, 0.5);
      group.add(cap);
    }
  }

  // ---------------------------------------------------------------
  // MOTION — emerge from core (1400ms, distance-staggered) + ambient drift
  // ---------------------------------------------------------------
  const dummy = new Object3D();
  const EMERGE_DUR = 0.9; // per-instance, staggered up to 0.5s -> ~1.4s total
  let elapsed = 0;

  const easeOut = (t) => 1 - Math.pow(1 - t, 3);

  const tick = (t, deltaMs) => {
    elapsed += deltaMs / 1000;
    const w = Math.PI * 2 * 0.05; // 0.05 Hz drift

    for (let i = 0; i < FIELD_COUNT; i++) {
      const raw = (elapsed - fieldDelay[i]) / EMERGE_DUR;
      const e = raw <= 0 ? 0 : raw >= 1 ? 1 : easeOut(raw);
      const ph = fieldPhase[i];
      const ax = fieldAnchors[i * 3];
      const ay = fieldAnchors[i * 3 + 1];
      const az = fieldAnchors[i * 3 + 2];
      dummy.position.set(
        ax * e + Math.sin(w * elapsed + ph) * 0.04 * e,
        ay * e + Math.sin(w * elapsed + ph * 1.3 + 2.1) * 0.04 * e,
        az * e + Math.sin(w * elapsed + ph * 0.7 + 4.2) * 0.04 * e
      );
      dummy.scale.setScalar(Math.max(e, 0.0001));
      dummy.updateMatrix();
      field.setMatrixAt(i, dummy.matrix);
    }
    field.instanceMatrix.needsUpdate = true;

    for (let i = 0; i < CORE_COUNT; i++) {
      const raw = elapsed / 0.6;
      const e = raw <= 0 ? 0 : raw >= 1 ? 1 : easeOut(raw);
      const ph = corePhase[i];
      dummy.position.set(
        coreAnchors[i * 3] * e + Math.sin(w * elapsed + ph) * 0.02 * e,
        coreAnchors[i * 3 + 1] * e + Math.sin(w * elapsed + ph + 2.0) * 0.02 * e,
        coreAnchors[i * 3 + 2] * e
      );
      dummy.scale.setScalar(Math.max(e, 0.0001));
      dummy.updateMatrix();
      core.setMatrixAt(i, dummy.matrix);
    }
    core.instanceMatrix.needsUpdate = true;
  };
  gsap.ticker.add(tick);

  // Weighted settle on the whole group entrance
  const tl = gsap.timeline();
  tl.fromTo(group.position, { y: -0.3 }, { y: 0, duration: 0.7, ease: 'power3.out' });
  tl.fromTo(
    group.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    0.2
  );

  // ---------------------------------------------------------------
  // CINEMATIC PRIMITIVES — apply every declared primitive via ctx
  // ---------------------------------------------------------------
  for (const p of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives[p.name];
    if (fn) primitiveHandles.push(fn(group, p.params ?? {}));
  }

  // ---------------------------------------------------------------
  // LIFECYCLE
  // ---------------------------------------------------------------
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    gsap.ticker.remove(tick);
    tl.kill();
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }
    field.dispose();
    core.dispose();
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
  };

  return group;
}
